import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import { Navigate, useLocation } from 'react-router-dom';
import { getUserAuthData, getUserRoles, UserRole } from '@/entities/User';
import { getRouteForbidden, getRouteMain } from '@/shared/const/router';

interface RequireAuthProps {
    children: React.ReactElement;
    roles?: UserRole[];
}

export function RequireAuth({ children, roles }: RequireAuthProps) {
    const auth = useSelector(getUserAuthData);
    const location = useLocation();
    const userRoles = useSelector(getUserRoles);

    const hasRequiredRoles = useMemo(() => {
        if (!roles) {
            return true;
        }

        return roles.some((requiredRole) => {
            const hasRole = userRoles?.includes(requiredRole);
            return hasRole;
        });
    }, [roles, userRoles]);

    if (!auth) {
        return (
            <Navigate to={getRouteMain()} state={{ from: location }} replace />
        );
    }

    if (!hasRequiredRoles) {
        return (
            <Navigate
                to={getRouteForbidden()}
                state={{ from: location }}
                replace
            />
        );
    }

    return children;
}

import { AxiosInstance } from 'axios';
import { UserSchema } from '@/entities/User';
import { CounterSchema } from '@/entities/Counter';
import { UISchema } from '@/features/UI';
import { rtkApi } from '@/shared/api/rtkApi';

export interface StateSchema {
    counter: CounterSchema;
    user: UserSchema;
    ui: UISchema;
    [rtkApi.reducerPath]: ReturnType<typeof rtkApi.reducer>;
}

export interface ThunkExtraArg {
    api: AxiosInstance;
}

export interface ThunkConfig<T> {
    rejectValue: T;
    extra: ThunkExtraArg;
    state: StateSchema;
}

import {
    combineReducers,
    configureStore,
    StateFromReducersMapObject,
} from '@reduxjs/toolkit';
import { PreloadedStateShapeFromReducersMapObject } from 'redux';
import { counterReducer } from '@/entities/Counter';
import { userReducer } from '@/entities/User';
import { $api } from '@/shared/api/api';
import { uiReducer } from '@/features/UI';
import { rtkApi } from '@/shared/api/rtkApi';
import { ThunkExtraArg } from './StateSchema';

export const rootReducers = {
    counter: counterReducer,
    user: userReducer,
    ui: uiReducer,
    [rtkApi.reducerPath]: rtkApi.reducer,
};

export const rootReducer = combineReducers(rootReducers);

export type RootState = StateFromReducersMapObject<typeof rootReducers>;
export type StorePreloadedState = Partial<
    PreloadedStateShapeFromReducersMapObject<typeof rootReducers>
>;

export function createReduxStore(initialState?: StorePreloadedState) {
    const extraArg: ThunkExtraArg = {
        api: $api,
    };

    const store = configureStore({
        reducer: rootReducer,
        devTools: __IS_DEV__,
        preloadedState: initialState,
        middleware: (getDefaultMiddleware) =>
            getDefaultMiddleware({
                thunk: {
                    extraArgument: extraArg,
                },
            }).concat(rtkApi.middleware),
    });

    return store;
}

export type AppDispatch = ReturnType<typeof createReduxStore>['dispatch'];

import { ReactNode } from 'react';
import { Provider } from 'react-redux';
import { createReduxStore, StorePreloadedState } from '../config/store';

interface StoreProviderProps {
    children?: ReactNode;
    initialState?: StorePreloadedState;
}

export const StoreProvider = (props: StoreProviderProps) => {
    const { children, initialState } = props;

    const store = createReduxStore(initialState);

    return <Provider store={store}>{children}</Provider>;
};

export interface CounterSchema {
    value: number;
}

